// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 value, uint256 timestamp, uint128 blockNum) public {
        vm.assume(value == 10 ether);
        vm.assume(timestamp > 0);
        vm.assume(blockNum % 15 != 0);
        vm.assume(blockNum > 0);
        vm.assume(timestamp > c.pastBlockTime());

        vm.warp(timestamp);
        vm.roll(blockNum);

        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");
        assertTrue(success);

        assertTrue(c.pastBlockTime() == timestamp + 1);
    }
}
